class Zufallszahlen {

    // Attribute 
    // TODO 1a Ergänze hier die Attribute zahl0 bis zahl3
    private int zahl0;
    private int zahl1;
    private int zahl2;
    private int zahl3;

    // TODO 2 
    private int [] zahlenFeld; 


    /**
     * Konstruktor für Objekte der Klasse Zufallszahlen.
     */
    Zufallszahlen() {
        // TODO 1b Belege die Attribute aus Aufgabe 1a mit beliebigen Zahlenwerten zwischen 1 und 6. 
        zahl0 = 1;
        zahl1 = 6;
        zahl2 = 2;
        zahl3 = 3; 


        // TODO 2
        zahlenFeld = new int[10];
    }

    /**
     * Diese Methode belegt das Feld zahlenFeld mit zufaelligen Werten. 
     */
    void zufaelligBelegen(){
        // TODO 3
        for(int i = 0; i < zahlenFeld.length; i++){
            zahlenFeld[i] = Random.randint(1, 6);
            System.out.println("Stelle " + i + ": " + zahlenFeld[i]);
        }
    }

    /**
     * Diese Methode belegt das Feld zahlenFeld mit zufaelligen Werten. 
     */
    void zweiWuerfel(){
        // TODO 4
        for(int i = 0; i < zahlenFeld.length; i++){
            zahlenFeld[i] =  Random.randint(1, 6) +  Random.randint(1, 6);
        }
    }
}

Zufallszahlen z = new Zufallszahlen(); 
z.zufaelligBelegen();
z.zweiWuerfel();
